#include <bits/stdc++.h>
using namespace std;

int N, M;
double px[20], py[20];

int coverable(double cx, double cy, double r) {
    int mask = 0;
    for (int i = 0; i < N; i++) {
        double dx = px[i] - cx, dy = py[i] - cy;
        if (dx*dx + dy*dy <= r*r + 1e-9) mask |= (1 << i);
    }
    return mask;
}

bool check(double r) {
    vector<int> circles;
    for (int i = 0; i < N; i++) {
        circles.push_back(coverable(px[i], py[i], r));
        for (int j = i+1; j < N; j++) {
            double dx = px[j]-px[i], dy = py[j]-py[i];
            double d2 = dx*dx + dy*dy;
            if (d2 > 4*r*r + 1e-9) continue;
            double mx = (px[i]+px[j])/2, my = (py[i]+py[j])/2;
            double h = sqrt(max(0.0, r*r - d2/4));
            double nx = -dy/sqrt(d2), ny = dx/sqrt(d2);
            circles.push_back(coverable(mx + h*nx, my + h*ny, r));
            circles.push_back(coverable(mx - h*nx, my - h*ny, r));
        }
    }
    int full = (1 << N) - 1;
    vector<int> dp(1 << N, INT_MAX);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << N); mask++) {
        if (dp[mask] == INT_MAX) continue;
        if (dp[mask] >= M) continue;
        // find lowest unset bit
        int bit = -1;
        for (int i = 0; i < N; i++) if (!(mask & (1<<i))) { bit = i; break; }
        if (bit == -1) continue;
        for (int c : circles) {
            if (c & (1 << bit)) {
                int nmask = mask | c;
                dp[nmask] = min(dp[nmask], dp[mask] + 1);
            }
        }
    }
    return dp[full] <= M;
}

