#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<double> x(N), y(N);
    for (int i = 0; i < N; i++) cin >> x[i] >> y[i];

    if (N == 0) {
        cout << fixed << setprecision(10) << 0.0 << '\n';
        return 0;
    }

    auto can = [&](double r) -> bool {
        vector<unsigned long long> cover;
        cover.reserve(N * N);

        // Candidate centers:
        // 1) each hero position itself
        // 2) for each pair of heroes with distance <= 2r, the two circle centers
        //    of radius r passing through both points
        auto add_mask_from_center = [&](double cx, double cy) {
            unsigned long long mask = 0;
            double rr = r * r + 1e-10;
            for (int i = 0; i < N; i++) {
                double dx = x[i] - cx;
                double dy = y[i] - cy;
                if (dx * dx + dy * dy <= rr) mask |= (1ULL << i);
            }
            cover.push_back(mask);
        };

        for (int i = 0; i < N; i++) {
            add_mask_from_center(x[i], y[i]);
        }

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                double dx = x[j] - x[i];
                double dy = y[j] - y[i];
                double d2 = dx * dx + dy * dy;
                double d = sqrt(d2);
                if (d > 2.0 * r + 1e-10) continue;
                if (d < 1e-12) continue;

                double mx = (x[i] + x[j]) * 0.5;
                double my = (y[i] + y[j]) * 0.5;

                double h = sqrt(max(0.0, r * r - (d * 0.5) * (d * 0.5)));
                double ux = -dy / d;
                double uy = dx / d;

                add_mask_from_center(mx + ux * h, my + uy * h);
                add_mask_from_center(mx - ux * h, my - uy * h);
            }
        }

        unsigned long long full = (N == 64 ? ~0ULL : ((1ULL << N) - 1));

        // Since typical constraints for this geometry/bitmask problem are small,
        // check whether union of at most M circles covers all heroes.
        if (M <= 1) {
            for (auto a : cover) if (a == full) return true;
            return false;
        }
        if (M == 2) {
            for (auto a : cover)
                for (auto b : cover)
                    if ((a | b) == full) return true;
            return false;
        }
        if (M >= N) return true;

        // General small M DFS with pruning
        sort(cover.begin(), cover.end());
        cover.erase(unique(cover.begin(), cover.end()), cover.end());

        function<bool(int, unsigned long long)> dfs = [&](int rem, unsigned long long cur) -> bool {
            if (cur == full) return true;
            if (rem == 0) return false;

            int first = -1;
            for (int i = 0; i < N; i++) {
                if (((cur >> i) & 1ULL) == 0) {
                    first = i;
                    break;
                }
            }

            for (auto m : cover) {
                if (((m >> first) & 1ULL) == 0) continue;
                if (dfs(rem - 1, cur | m)) return true;
            }
            return false;
        };

        return dfs(M, 0);
    };

    double lo = 0.0, hi = 0.0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            double dx = x[i] - x[j];
            double dy = y[i] - y[j];
            hi = max(hi, sqrt(dx * dx + dy * dy));
        }
    }

    for (int it = 0; it < 60; it++) {
        double mid = (lo + hi) * 0.5;
        if (can(mid)) hi = mid;
        else lo = mid;
    }

    cout << fixed << setprecision(10) << hi << '\n';
    return 0;
}

