public class Main {
    static int N, M;
    static double[] X, Y;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt(); M = sc.nextInt();
        X = new double[N]; Y = new double[N];
        for (int i = 0; i < N; i++) { X[i] = sc.nextDouble(); Y[i] = sc.nextDouble(); }

        double lo = 0, hi = 2e9;
        for (int iter = 0; iter < 100; iter++) {
            double mid = (lo + hi) / 2;
            if (check(mid)) hi = mid; else lo = mid;
        }
        System.out.printf("%.10f%n", hi);
    }

    static boolean check(double r) {
        List<long[]> masks = new ArrayList<>();
        // single points
        for (int i = 0; i < N; i++) masks.add(new long[]{cover(X[i], Y[i], r)});
        // pairs
        for (int i = 0; i < N; i++) for (int j = i+1; j < N; j++) {
            double dx = X[j]-X[i], dy = Y[j]-Y[i];
            double d = Math.sqrt(dx*dx+dy*dy);
            if (d > 2*r+1e-9) continue;
            double mx = (X[i]+X[j])/2, my = (Y[i]+Y[j])/2;
            double h = Math.sqrt(Math.max(0, r*r - d*d/4));
            double px = -dy/d*h, py = dx/d*h;
            masks.add(new long[]{cover(mx+px, my+py, r)});
            masks.add(new long[]{cover(mx-px, my-py, r)});
        }
        int full = (1<<N)-1;
        int[] dp = new int[full+1]; Arrays.fill(dp, Integer.MAX_VALUE/2); dp[0]=0;
        for (int mask = 0; mask <= full; mask++) {
            if (dp[mask] >= M) continue;
            for (long[] ms : masks) {
                int nm = mask | (int)ms[0];
                if (dp[nm] > dp[mask]+1) dp[nm] = dp[mask]+1;
            }
        }
        return dp[full] <= M;
    }

    static long cover(double cx, double cy, double r) {
        long mask = 0;
        for (int i = 0; i < N; i++) {
            double dx = X[i]-cx, dy = Y[i]-cy;
            if (dx*dx+dy*dy <= r*r+1e-9) mask |= (1<<i);
        }
        return mask;
    }
}

import java.io.*;
import java.util.*;

/*
Assumption from the statement:
- There are N heroes on a line (the surface), each at some coordinate.
- Megumin can cast the spell M times.
- One cast destroys all heroes within distance r from the chosen center.
- We must find the minimum r so that all heroes can be covered by at most M intervals of length 2r.

This is the standard "minimum radius to cover points with M intervals" problem.

Input format assumed:
N M
x1 x2 ... xN

Works also if coordinates are given across multiple lines.

Approach:
1. Sort coordinates.
2. Binary search the answer r.
3. Feasibility check for a fixed r:
   greedily place an interval [x[i], x[i] + 2r] starting from the leftmost uncovered hero,
   and count how many casts are needed.
   If casts <= M, then r is feasible.

Time complexity:
- Sorting: O(N log N)
- Each check: O(N)
- Binary search over integer radius: O(log range)
Total: O(N log N + N log range)

If coordinates are integers, the minimum radius is also treated as an integer.
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N, M;
    static long[] x;

    static boolean can(long r) {
        int used = 0;
        int i = 0;
        while (i < N) {
            used++;
            if (used > M) return false;

            long coverRight = x[i] + 2L * r;
            i++;
            while (i < N && x[i] <= coverRight) i++;
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = (int) fs.nextLong();
        M = (int) fs.nextLong();

        x = new long[N];
        for (int i = 0; i < N; i++) x[i] = fs.nextLong();

        Arrays.sort(x);

        long low = -1; // infeasible
        long high = x[N - 1] - x[0]; // always feasible with 1 cast if M>=1, otherwise still safe upper bound

        while (high - low > 1) {
            long mid = low + (high - low) / 2;
            if (can(mid)) high = mid;
            else low = mid;
        }

        System.out.println(high);
    }
}

#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAX_N 50

typedef struct {
    double x, y;
} Point;

int n, m;
Point heroes[MAX_N];
int used[MAX_N];

double dist(Point a, Point b) {
    return sqrt((a.x - b.x)*(a.x - b.x) + (a.y - b.y)*(a.y - b.y));
}

// Check if we can cover all points with m circles of radius r
int can_cover(double r) {
    int i, j, k;
    // Try all pairs of points as circle centers (or single points)
    // We will try to cover greedily: choose uncovered point, try to cover
    // as many as possible with a circle centered at that point or midpoint of two points.

    int covered[MAX_N] = {0};
    int count_covered = 0;
    int explosions = 0;

    while (count_covered < n && explosions < m) {
        // Find first uncovered point
        int best_i = -1;
        for (i = 0; i < n; i++) {
            if (!covered[i]) {
                best_i = i;
                break;
            }
        }
        if (best_i == -1) break;

        // Try covering as many as possible with circle centered at best_i
        int best_cnt = 0;
        double best_cx = heroes[best_i].x, best_cy = heroes[best_i].y;

        // Option 1: center at hero best_i
        int cnt = 0;
        for (j = 0; j < n; j++) {
            if (!covered[j] && dist(heroes[best_i], heroes[j]) <= r + 1e-9)
                cnt++;
        }
        if (cnt > best_cnt) {
            best_cnt = cnt;
            best_cx = heroes[best_i].x;
            best_cy = heroes[best_i].y;
        }

        // Option 2: center at each other hero (if dist <= 2r)
        for (j = 0; j < n; j++) {
            if (j == best_i) continue;
            double d = dist(heroes[best_i], heroes[j]);
            if (d > 2*r + 1e-9) continue;
            // Find two possible circle centers that pass through both points
            double mx = (heroes[best_i].x + heroes[j].x)/2.0;
            double my = (heroes[best_i].y + heroes[j].y)/2.0;
            double half_d = d/2.0;
            double h = sqrt(r*r - half_d*half_d);
            double dx = (heroes[j].x - heroes[best_i].x)/d;
            double dy = (heroes[j].y - heroes[best_i].y)/d;

            double cx1 = mx - dy * h;
            double cy1 = my + dx * h;
            double cx2 = mx + dy * h;
            double cy2 = my - dx * h;

            for (int t = 0; t < 2; t++) {
                double cx = (t == 0) ? cx1 : cx2;
                double cy = (t == 0) ? cy1 : cy2;
                cnt = 0;
                for (k = 0; k < n; k++) {
                    if (!covered[k]) {
                        Point p = {cx, cy};
                        if (dist(p, heroes[k]) <= r + 1e-9)
                            cnt++;
                    }
                }
                if (cnt > best_cnt) {
                    best_cnt = cnt;
                    best_cx = cx;
                    best_cy = cy;
                }
            }
        }

        // Now apply best circle
        Point center = {best_cx, best_cy};
        for (i = 0; i < n; i++) {
            if (!covered[i] && dist(center, heroes[i]) <= r + 1e-9) {
                covered[i] = 1;
                count_covered++;
            }
        }
        explosions++;
    }
    return count_covered == n;
}

int main() {
    int i;
    scanf("%d %d", &n, &m);
    for (i = 0; i < n; i++) {
        scanf("%lf %lf", &heroes[i].x, &heroes[i].y);
    }

    double lo = 0.0, hi = 2000.0;
    for (i = 0; i < 60; i++) {
        double mid = (lo + hi) / 2.0;
        if (can_cover(mid))
            hi = mid;
        else
            lo = mid;
    }

    printf("%.10f\n", hi);
    return 0;
}

