int N, M;
double px[MAXN], py[MAXN];
int cover[MAXN*MAXN*3 + MAXN]; // coverage masks for candidate circles
int ncircles;
int dp[1<<MAXN];

void gen_circles(double r, int *masks, int *nm) {
    *nm = 0;
    // For each point, circle centered at it
    // For each pair, up to 2 circles passing through both with radius r
    for(int i=0;i<N;i++) {
        for(int j=i;j<N;j++) {
            double dx=px[i]-px[j], dy=py[i]-py[j];
            double d=sqrt(dx*dx+dy*dy);
            double cx[2],cy[2]; int nc=0;
            if(j==i){cx[0]=px[i];cy[0]=py[i];nc=1;}
            else if(d>2*r+1e-9) continue;
            else if(d<1e-12){cx[0]=px[i];cy[0]=py[i];nc=1;}
            else {
                double mx=(px[i]+px[j])/2, my=(py[i]+py[j])/2;
                double h=sqrt(r*r-(d/2)*(d/2));
                double ex=-(py[j]-py[i])/d, ey=(px[j]-px[i])/d;
                cx[0]=mx+h*ex;cy[0]=my+h*ey;
                cx[1]=mx-h*ex;cy[1]=my-h*ey;
                nc=2;
            }
            for(int c=0;c<nc;c++){
                int mask=0;
                for(int k=0;k<N;k++){double dx2=cx[c]-px[k],dy2=cy[c]-py[k];if(dx2*dx2+dy2*dy2<=r*r+1e-9)mask|=(1<<k);}
                masks[(*nm)++]=mask;
            }
        }
    }
}

int can_cover(double r){
    int masks[MAXN*MAXN*3+MAXN],nm;
    gen_circles(r,masks,&nm);
    int full=(1<<N)-1;
    for(int i=0;i<=full;i++) dp[i]=1e9;
    dp[0]=0;
    for(int mask=0;mask<full;mask++){
        if(dp[mask]>=M) continue;
        int bit=mask^(mask|(mask+1)); // lowest 0 bit... 
        // find first unset bit
        int fb=-1; for(int b=0;b<N;b++) if(!(mask&(1<<b))){fb=b;break;}
        for(int c=0;c<nm;c++){
            if(masks[c]&(1<<fb)){
                int nm2=mask|masks[c];
                if(dp[nm2]>dp[mask]+1) dp[nm2]=dp[mask]+1;
            }
        }
    }
    return dp[full]<=M;
}

