#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

int N, M;
Point *p;

/* Check if all points can be covered by at most M circles of radius r */
int can_cover(double r) {
    if (N == 0) return 1;

    int full = 1 << N;
    int *cover = (int *)malloc(sizeof(int) * full);
    if (!cover) exit(1);

    /* For every subset, determine whether it can be covered by one circle of radius r */
    for (int mask = 0; mask < full; mask++) cover[mask] = 0;
    cover[0] = 1;

    const double EPS = 1e-9;

    /* Any single point can be covered */
    for (int i = 0; i < N; i++) cover[1 << i] = 1;

    /* Build all coverable subsets from circles determined by 1 or 2 boundary points */
    for (int i = 0; i < N; i++) {
        /* Circle centered at point i */
        int mask = 0;
        for (int k = 0; k < N; k++) {
            double dx = p[k].x - p[i].x;
            double dy = p[k].y - p[i].y;
            if (dx * dx + dy * dy <= r * r + EPS) mask |= (1 << k);
        }
        cover[mask] = 1;

        for (int j = i + 1; j < N; j++) {
            double dx = p[j].x - p[i].x;
            double dy = p[j].y - p[i].y;
            double d2 = dx * dx + dy * dy;
            double d = sqrt(d2);

            if (d > 2.0 * r + EPS) continue;

            double mx = (p[i].x + p[j].x) / 2.0;
            double my = (p[i].y + p[j].y) / 2.0;

            double h = sqrt(fmax(0.0, r * r - (d * d) / 4.0));
            double ux = -dy / d;
            double uy = dx / d;

            for (int t = 0; t < 2; t++) {
                double cx = mx + (t == 0 ? h : -h) * ux;
                double cy = my + (t == 0 ? h : -h) * uy;

                int m = 0;
                for (int k = 0; k < N; k++) {
                    double ddx = p[k].x - cx;
                    double ddy = p[k].y - cy;
                    if (ddx * ddx + ddy * ddy <= r * r + 1e-8) m |= (1 << k);
                }
                cover[m] = 1;
            }
        }
    }

    /* DP over subsets: minimum number of circles needed */
    int *dp = (int *)malloc(sizeof(int) * full);
    if (!dp) exit(1);

    for (int mask = 0; mask < full; mask++) dp[mask] = M + 1;
    dp[0] = 0;

    for (int mask = 0; mask < full; mask++) {
        if (dp[mask] >= M) continue;
        int rem = ((full - 1) ^ mask);

        /* iterate all one-circle coverable subsets */
        for (int sub = rem; sub; sub = (sub - 1) & rem) {
            if (cover[sub]) {
                int nmask = mask | sub;
                if (dp[nmask] > dp[mask] + 1) dp[nmask] = dp[mask] + 1;
            }
        }
    }

    int ok = (dp[full - 1] <= M);

    free(cover);
    free(dp);
    return ok;
}

int main(void) {
    if (scanf("%d %d", &N, &M) != 2) return 0;

    p = (Point *)malloc(sizeof(Point) * N);
    if (!p) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    if (N == 0) {
        printf("0.0000000000\n");
        free(p);
        return 0;
    }

    double lo = 0.0, hi = 0.0;

    /* Upper bound: max pair distance */
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            double dx = p[i].x - p[j].x;
            double dy = p[i].y - p[j].y;
            double d = sqrt(dx * dx + dy * dy);
            if (hi < d) hi = d;
        }
    }

    /* Binary search answer */
    for (int it = 0; it < 50; it++) {
        double mid = (lo + hi) / 2.0;
        if (can_cover(mid)) hi = mid;
        else lo = mid;
    }

    printf("%.10f\n", hi);

    free(p);
    return 0;
}

import sys
import math

input = sys.stdin.readline

def can_cover(points, r, m):
    n = len(points)
    if n == 0:
        return True
    if m == 0:
        return False

    # Try to cover the first uncovered point
    uncovered = points[:]
    # Greedy: choose a point, place circle at that point or at midpoint with another
    for i in range(len(uncovered)):
        for j in range(i, len(uncovered)):
            # center between i and j or at i/j
            centers = []
            if i == j:
                centers.append(uncovered[i])
            else:
                # two possible centers from intersection of two circles radius r
                x1, y1 = uncovered[i]
                x2, y2 = uncovered[j]
                d = math.hypot(x2 - x1, y2 - y1)
                if d > 2 * r + 1e-9:
                    continue
                if d == 0:
                    centers.append((x1, y1))
                else:
                    midx = (x1 + x2) / 2
                    midy = (y1 + y2) / 2
                    h = math.sqrt(max(0, r*r - (d/2)**2))
                    dx = (y1 - y2) * h / d
                    dy = (x2 - x1) * h / d
                    centers.append((midx + dx, midy + dy))
                    centers.append((midx - dx, midy - dy))
            for cx, cy in centers:
                remaining = []
                for (px, py) in uncovered:
                    if math.hypot(px - cx, py - cy) > r + 1e-9:
                        remaining.append((px, py))
                if can_cover(remaining, r, m - 1):
                    return True
    return False

def main():
    n, m = map(int, input().split())
    points = [tuple(map(float, input().split())) for _ in range(n)]

    lo, hi = 0.0, 2000.0
    for _ in range(50):
        mid = (lo + hi) / 2
        if can_cover(points, mid, m):
            hi = mid
        else:
            lo = mid
    print(f"{hi:.6f}")

