import sys
from itertools import combinations
import math

def dist(a, b):
    return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2)

def circle_from_two_points(p1, p2, r):
    # Returns centers of circles of radius r passing through p1 and p2
    d = dist(p1, p2)
    if d > 2*r + 1e-9:
        return []
    if d < 1e-12:
        return [(p1[0], p1[1])]
    mx, my = (p1[0]+p2[0])/2, (p1[1]+p2[1])/2
    if d > 2*r:
        return [(mx, my)]
    h = math.sqrt(max(0, r*r - (d/2)**2))
    dx, dy = (p2[0]-p1[0])/d, (p2[1]-p1[1])/d
    return [(mx + h*(-dy), my + h*dx), (mx - h*(-dy), my - h*dx)]

def can_cover(points, m, r):
    if not points:
        return True
    if m == 0:
        return False
    # Pick first point, must be covered
    p = points[0]
    candidates = []
    # Circle centered at p
    candidates.append((p[0], p[1]))
    # Circles through p and each other point
    for q in points[1:]:
        for c in circle_from_two_points(p, q, r):
            candidates.append(c)
    for cx, cy in candidates:
        remaining = [pt for pt in points if (pt[0]-cx)**2 + (pt[1]-cy)**2 > r*r + 1e-9]
        if can_cover(remaining, m-1, r):
            return True
    return False

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N, M = int(input_data[idx]), int(input_data[idx+1])
    idx += 2
    points = []
    for _ in range(N):
        x, y = float(input_data[idx]), float(input_data[idx+1])
        idx += 2
        points.append((x, y))

    lo, hi = 0.0, 2e9
    for _ in range(100):
        mid = (lo + hi) / 2
        if can_cover(points, M, mid):
            hi = mid
        else:
            lo = mid
    print(f"{hi:.10f}")

solve()
